import{_ as e,C as t,c as n,o as i,j as a,G as r,a0 as o,b as l,a as s,w as d,a1 as g}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Workshop: Geavanceerde mentale speltraining (3-4 uur)","description":"","frontmatter":{},"headers":[],"relativePath":"nl/workshop.md","filePath":"nl/workshop.md"}');const h=e({name:"nl/workshop.md"},[["render",function(e,u,h,c,p,m){const k=t("AdBanner"),b=t("Mermaid"),v=t("AdInArticle");return i(),n("div",null,[u[4]||(u[4]=a("h1",{id:"workshop-geavanceerde-mentale-speltraining-3-4-uur",tabindex:"-1"},[s("Workshop: Geavanceerde mentale speltraining (3-4 uur) "),a("a",{class:"header-anchor",href:"#workshop-geavanceerde-mentale-speltraining-3-4-uur","aria-label":'Permalink to "Workshop: Geavanceerde mentale speltraining (3-4 uur)"'},"​")],-1)),r(k),u[5]||(u[5]=o('<h2 id="overzicht" tabindex="-1">Overzicht <a class="header-anchor" href="#overzicht" aria-label="Permalink to &quot;Overzicht&quot;">​</a></h2><p>Deze workshop is een geavanceerde theoretische sessie van 3-4 uur voor 6-8 topspelers, gericht op diepgaand psychologisch werk en leren vanuit kwetsbaarheid. Het gaat verder dan basis mentale vaardigheden en verkent het innerlijke spel op een diepgaand niveau.</p><div class="tip custom-block"><p class="custom-block-title">Deze handleiding bestaat uit twee secties.</p><ul><li><strong><a href="#voor-deelnemers">Voor deelnemers</a></strong> - Wat spelers zullen ervaren en leren</li><li><strong><a href="#voor-begeleiders">Voor begeleiders</a></strong> - Hoe geef je de workshop als coördinator mentale prestaties?</li></ul></div><p><strong>Verschil met de beginnerssessie:</strong></p><ul><li><strong>Beginners (2-3 uur):</strong> Introductie tot mentale spelconcepten → <a href="/en/mental-journey/session-guide">Zie Mentale Reisgids</a></li><li><strong>Gevorderd (3-4 uur):</strong> Diepgaand psychologisch werk met kwetsbaarheidsoefeningen (deze pagina)</li></ul><h2 id="sneltoegang" tabindex="-1">Sneltoegang <a class="header-anchor" href="#sneltoegang" aria-label="Permalink to &quot;Sneltoegang&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Sectie</th><th>Doel</th><th>Toegang</th></tr></thead><tbody><tr><td><strong>Voor deelnemers</strong></td><td>Wat je kunt verwachten en hoe je je kunt voorbereiden</td><td><a href="#voor-deelnemers">Sectie bekijken</a></td></tr><tr><td><strong>Voor begeleiders</strong></td><td>Complete sessiehandleiding en oefeningen</td><td><a href="#voor-facilitatoren">Sectie bekijken</a></td></tr><tr><td><strong>Sessiematerialen</strong></td><td>Oefeningen en werkbladen</td><td><a href="#facilitator-materials">Materialen bekijken</a></td></tr><tr><td><strong>Gerelateerde handleidingen</strong></td><td>Andere trainingsvormen</td><td><a href="/en/mental-journey/">Mentale Reis</a> • <a href="/en/training-camp">Trainingskamp</a></td></tr></tbody></table><hr><h2 id="voor-deelnemers" tabindex="-1">Voor deelnemers <a class="header-anchor" href="#voor-deelnemers" aria-label="Permalink to &quot;Voor deelnemers&quot;">​</a></h2><h3 id="wat-kun-je-verwachten" tabindex="-1">Wat kun je verwachten? <a class="header-anchor" href="#wat-kun-je-verwachten" aria-label="Permalink to &quot;Wat kun je verwachten?&quot;">​</a></h3><p>Dit is geen doorsnee trainingssessie. Je neemt deel aan diepgaande discussies over de mentale en emotionele aspecten van pétanque die zelden openlijk besproken worden.</p><p><strong>Deze workshop is:</strong></p><ul><li>✅ Een veilige plek om je innerlijke gedachten en angsten te verkennen</li><li>✅ Leren van kwetsbaarheden samen met teamgenoten</li><li>✅ Het verband tussen mentale patronen en prestaties</li><li>✅ Het opbouwen van psychologische intelligentie binnen het team</li></ul><p><strong>Deze workshop is NIET:</strong></p><ul><li>❌ Technische coaching of tactische training</li><li>❌ Therapie of begeleiding</li><li>❌ Toespraken over positief denken of motivatie</li><li>❌ Oordeel of kritiek</li></ul><h3 id="sessiestructuur" tabindex="-1">Sessiestructuur <a class="header-anchor" href="#sessiestructuur" aria-label="Permalink to &quot;Sessiestructuur&quot;">​</a></h3>',16)),(i(),l(g,null,{default:d(()=>[r(b,{id:"mermaid-167",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BWorkshopsessie%5D%20--%3E%20B%5BBasiscursus%2060%20min.%5D%0A%20%20%20%20B%20--%3E%20C%5BIntensief%20werk%20van%2090%20minuten%5D%0A%20%20%20%20C%20--%3E%20D%5BIntegratie%2045%20min.%5D%0A%20%20%20%20D%20--%3E%20E%5BSluitingstijd%3A%2015%20minuten%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20B%20fill%3A%23fff4e1%0A%20%20%20%20style%20C%20fill%3A%23ffe4e1%0A%20%20%20%20style%20D%20fill%3A%23e3f2fd%0A%20%20%20%20style%20E%20fill%3A%23f3e5f5%0A"})]),fallback:d(()=>[...u[0]||(u[0]=[s(" Loading... ",-1)])]),_:1})),u[6]||(u[6]=o('<p><strong>Totale duur:</strong> 3-4 uur <strong>Groepsgrootte:</strong> 6-8 spelers <strong>Format:</strong> Kringgesprek met gestructureerde oefeningen</p><h3 id="wat-je-zult-leren" tabindex="-1">Wat je zult leren <a class="header-anchor" href="#wat-je-zult-leren" aria-label="Permalink to &quot;Wat je zult leren&quot;">​</a></h3><h4 id="fase-1-basis-60-min" tabindex="-1">Fase 1: Basis (60 min) <a class="header-anchor" href="#fase-1-basis-60-min" aria-label="Permalink to &quot;Fase 1: Basis (60 min)&quot;">​</a></h4><ul><li>Basisregels voor psychologische veiligheid</li><li>De &quot;Check-in Matrix&quot; - het erkennen van je huidige toestand.</li><li>De &quot;IJsberg van Pétanque&quot; - het verkennen van verborgen gedachten</li></ul><h4 id="fase-2-intensief-werk-90-min" tabindex="-1">Fase 2: Intensief werk (90 min) <a class="header-anchor" href="#fase-2-intensief-werk-90-min" aria-label="Permalink to &quot;Fase 2: Intensief werk (90 min)&quot;">​</a></h4><ul><li>Een handleiding voor je teamgenoten maken</li><li>Het verband tussen mentale patronen en prestaties.</li><li>&quot;Angst in een hoed&quot; - isolatie doorbreken door gedeelde kwetsbaarheid</li></ul><h4 id="fase-3-integratie-45-min" tabindex="-1">Fase 3: Integratie (45 min) <a class="header-anchor" href="#fase-3-integratie-45-min" aria-label="Permalink to &quot;Fase 3: Integratie (45 min)&quot;">​</a></h4><ul><li>Je innerlijke criticus omvormen tot een innerlijke coach.</li><li>Teamprotocollen opstellen voor wedstrijden</li><li>Praktische tips voor op de piste</li></ul><h4 id="fase-4-afronding-15-min" tabindex="-1">Fase 4: Afronding (15 min) <a class="header-anchor" href="#fase-4-afronding-15-min" aria-label="Permalink to &quot;Fase 4: Afronding (15 min)&quot;">​</a></h4><ul><li>Reflectie en toewijding</li><li>Nazorg</li></ul><h3 id="basisregels" tabindex="-1">Basisregels <a class="header-anchor" href="#basisregels" aria-label="Permalink to &quot;Basisregels&quot;">​</a></h3><p>Voordat de sessie begint, stemmen alle deelnemers ermee in om:</p><div class="tip custom-block"><p class="custom-block-title">De Container - Essentiële basisregels</p><ol><li><strong>Vertrouwelijkheid</strong> - Wat hier gezegd wordt, blijft hier.</li><li><strong>De Vegas-regel</strong> - Lessen verlaten de kamer, verhalen blijven.</li><li><strong>Niet repareren</strong> - Wees getuige en probeer te begrijpen, probeer het niet op te lossen.</li><li><strong>Recht om te passeren</strong> - Kwetsbaarheid kan niet worden afgedwongen</li><li><strong>Respecteer het proces</strong> - Vertrouw op het ongemak</li></ol></div><h3 id="wat-mee-te-nemen" tabindex="-1">Wat mee te nemen <a class="header-anchor" href="#wat-mee-te-nemen" aria-label="Permalink to &quot;Wat mee te nemen&quot;">​</a></h3><p><strong>Vereist:</strong></p><ul><li>Een open houding en de bereidheid om te delen</li><li>Jouw eigen ervaringen en uitdagingen</li><li>Respect voor de kwetsbaarheid van anderen</li></ul><p><strong>Optioneel:</strong></p><ul><li>Notitieboekje voor persoonlijke reflecties</li><li>Vragen over specifieke psychische problemen</li></ul><h3 id="belangrijkste-activiteiten-die-je-zult-ervaren" tabindex="-1">Belangrijkste activiteiten die je zult ervaren <a class="header-anchor" href="#belangrijkste-activiteiten-die-je-zult-ervaren" aria-label="Permalink to &quot;Belangrijkste activiteiten die je zult ervaren&quot;">​</a></h3><h4 id="de-incheckmatrix" tabindex="-1">De incheckmatrix <a class="header-anchor" href="#de-incheckmatrix" aria-label="Permalink to &quot;De incheckmatrix&quot;">​</a></h4><p>Plaats jezelf op een raster van energie en stemming. Accepteer dat we allemaal verschillende gemoedstoestanden hebben.</p><h4 id="de-ijsberg-van-petanque" tabindex="-1">De ijsberg van pétanque <a class="header-anchor" href="#de-ijsberg-van-petanque" aria-label="Permalink to &quot;De ijsberg van pétanque&quot;">​</a></h4><p>Ontdek wat er onder de oppervlakte speelt - de gedachten en angsten die niemand ziet.</p><h4 id="de-gebruikershandleiding" tabindex="-1">De gebruikershandleiding <a class="header-anchor" href="#de-gebruikershandleiding" aria-label="Permalink to &quot;De gebruikershandleiding&quot;">​</a></h4><p>Maak een handleiding voor jezelf, zodat je teamgenoten begrijpen hoe ze je kunnen ondersteunen.</p><h4 id="angst-in-een-hoed" tabindex="-1">Angst in een hoed <a class="header-anchor" href="#angst-in-een-hoed" aria-label="Permalink to &quot;Angst in een hoed&quot;">​</a></h4><p>Deel anoniem je diepste angsten en hoor hoe ze worden bevestigd door lotgenoten. Doorbrek het isolement.</p><h4 id="herkadering-van-de-innerlijke-criticus" tabindex="-1">Herkadering van de innerlijke criticus <a class="header-anchor" href="#herkadering-van-de-innerlijke-criticus" aria-label="Permalink to &quot;Herkadering van de innerlijke criticus&quot;">​</a></h4><p>Transformeer negatieve zelfpraat in ondersteunende coachingstaal.</p><h3 id="na-de-workshop" tabindex="-1">Na de workshop <a class="header-anchor" href="#na-de-workshop" aria-label="Permalink to &quot;Na de workshop&quot;">​</a></h3><p>Je gaat naar huis met:</p><ul><li>Een dieper inzicht in je mentale patronen</li><li>Teamprotocollen voor onderlinge ondersteuning</li><li>Herformuleringen van innerlijke coach-uitdrukkingen</li><li>Verbinding met teamgenoten door gedeelde kwetsbaarheid</li><li>Praktische instrumenten voor concurrentie</li></ul><div class="warning custom-block"><p class="custom-block-title">Kwetsbaarheidskater</p><p>Na een openhartig gesprek kun je je blootgesteld voelen of spijt hebben. Dat is normaal. De begeleider neemt binnen 24 uur contact met je op. Onthoud: wat je hebt gedeeld, heeft iedereen geholpen.</p></div>',33)),r(v),u[7]||(u[7]=o('<hr><h2 id="voor-begeleiders" tabindex="-1">Voor begeleiders <a class="header-anchor" href="#voor-begeleiders" aria-label="Permalink to &quot;Voor begeleiders&quot;">​</a></h2><h3 id="jouw-rol-als-coordinator-mentale-prestaties" tabindex="-1">Jouw rol als coördinator mentale prestaties <a class="header-anchor" href="#jouw-rol-als-coordinator-mentale-prestaties" aria-label="Permalink to &quot;Jouw rol als coördinator mentale prestaties&quot;">​</a></h3><p>Als <strong>Mental Performance Coordinator (MPC)</strong> faciliteer je diepgaande gesprekken over het mentale aspect van de wedstrijd, waardoor een veilige psychologische omgeving ontstaat die zich vertaalt in prestaties op de piste.</p><div class="warning custom-block"><p class="custom-block-title">Kritisch concept</p><p><strong>Je bent geen technische coach of therapeut.</strong> Jouw rol is het faciliteren van op kwetsbaarheid gebaseerd leren, waardoor spelers het verband tussen hun innerlijke gedachten en hun prestaties leren begrijpen.</p></div><h3 id="jouw-verantwoordelijkheden" tabindex="-1">Jouw verantwoordelijkheden <a class="header-anchor" href="#jouw-verantwoordelijkheden" aria-label="Permalink to &quot;Jouw verantwoordelijkheden&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">Belangrijkste verantwoordelijkheden</p><ul><li><strong>Begeleid de discussie, geef geen college</strong> - Je stuurt de discussie, je leert geen technieken aan.</li><li><strong>Bescherm de ruimte</strong> - Creëer en behoud psychologische veiligheid</li><li><strong>Verbind theorie met praktijk</strong> - Verbind website-inhoud met innerlijke ervaring.</li><li><strong>Houd de groepsdynamiek in de gaten</strong> - Let op wie betrokken is en wie weerstand biedt.</li><li><strong>Bewaar grenzen</strong> - Weet wanneer je professionele hulp moet inschakelen.</li></ul></div><h3 id="voorbereiding-voorafgaand-aan-de-workshop" tabindex="-1">Voorbereiding voorafgaand aan de workshop <a class="header-anchor" href="#voorbereiding-voorafgaand-aan-de-workshop" aria-label="Permalink to &quot;Voorbereiding voorafgaand aan de workshop&quot;">​</a></h3><h3 id="essentiele-competenties" tabindex="-1">Essentiële competenties <a class="header-anchor" href="#essentiele-competenties" aria-label="Permalink to &quot;Essentiële competenties&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Competentie</th><th>Wat het betekent</th><th>Hoe te ontwikkelen</th></tr></thead><tbody><tr><td><strong>Emotionele intelligentie</strong></td><td>Detecteer micro-uitdrukkingen van ongemak</td><td>Oefen actieve observatie.</td></tr><tr><td><strong>Neutrale Autoriteit</strong></td><td>Dwing respect af zonder technische vaardigheid.</td><td>Bouw geloofwaardigheid op door aanwezigheid.</td></tr><tr><td><strong>Sportcontext</strong></td><td>Inzicht in drukmechanismen</td><td>Leer de terminologie en cultuur van pétanque.</td></tr><tr><td><strong>Verbale Aikido</strong></td><td>Ga mee in het verzet, vecht er niet tegen.</td><td>Oefen niet-defensieve communicatie.</td></tr></tbody></table><details class="details custom-block"><summary>Belangrijke pétanque-termen die je moet kennen</summary><ul><li><strong>Carreau</strong> - Perfecte stoot die de boule van de tegenstander verplaatst.</li><li><strong>Bibber</strong> - De &quot;yips&quot; - onvrijwillige trilling tijdens het loslaten</li><li><strong>Donnée</strong> - Het &quot;gegeven&quot; - het terrein accepteren zoals het is</li><li><strong>Portée</strong> - Werpen zonder stuiteren</li><li><strong>Roulette</strong> - Rollende opname</li><li><strong>Cochonnet</strong> - De doelbal (jack)</li></ul></details><h2 id="fysieke-opstelling-de-magische-cirkel" tabindex="-1">Fysieke opstelling: De magische cirkel <a class="header-anchor" href="#fysieke-opstelling-de-magische-cirkel" aria-label="Permalink to &quot;Fysieke opstelling: De magische cirkel&quot;">​</a></h2><h3 id="locatievereisten" tabindex="-1">Locatievereisten <a class="header-anchor" href="#locatievereisten" aria-label="Permalink to &quot;Locatievereisten&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Kritieke configuratie</p><p><strong>Kies een neutrale plek, weg van de piste.</strong> Dit geeft aan dat je van fysiek naar mentaal werk overgaat.</p><p>Vereisten:</p><ul><li>✅ Geluidsdicht of privé</li><li>✅ Comfortabele temperatuur</li><li>✅ Geen afleiding (telefoons uit)</li><li>✅ Natuurlijk licht indien mogelijk</li><li>✅ Gescheiden van het trainingsgebied</li></ul></div><h3 id="de-cirkelconfiguratie" tabindex="-1">De cirkelconfiguratie <a class="header-anchor" href="#de-cirkelconfiguratie" aria-label="Permalink to &quot;De cirkelconfiguratie&quot;">​</a></h3><p><strong>Zitplaatsen:</strong></p><ul><li>Een perfecte cirkel van stoelen</li><li><strong>GEEN TAFELS</strong> - Tafels vormen barrières en verbergen lichaamstaal.</li><li>Alle stoelen op dezelfde hoogte (geen elektrische verstelmogelijkheden)</li><li>De coördinator zit in een kring (niet vooraan).</li></ul><p><strong>Centrale artefacten:</strong></p><ul><li>Leg de boules en cochonnet in het midden</li><li>Verankert het werk aan de sport.</li><li>Visuele herinnering aan een gedeeld doel</li></ul>',19)),(i(),l(g,null,{default:d(()=>[r(b,{id:"mermaid-632",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BFysieke%20ruimte%5D%20--%3E%20B%5BSignalen%20van%20een%20mentale%20omslag%5D%0A%20%20%20%20A%20--%3E%20C%5BGeen%20barri%C3%A8res%5D%0A%20%20%20%20A%20--%3E%20D%5BGelijke%20positionering%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BPsychologische%20veiligheid%5D%0A%20%20%20%20C%20--%3E%20E%0A%20%20%20%20D%20--%3E%20E%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20E%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...u[1]||(u[1]=[s(" Loading... ",-1)])]),_:1})),u[8]||(u[8]=o('<h2 id="sessie-indeling-3-4-uur" tabindex="-1">Sessie-indeling (3-4 uur) <a class="header-anchor" href="#sessie-indeling-3-4-uur" aria-label="Permalink to &quot;Sessie-indeling (3-4 uur)&quot;">​</a></h2><h3 id="fase-1-basis-60-minuten" tabindex="-1">Fase 1: Basis (60 minuten) <a class="header-anchor" href="#fase-1-basis-60-minuten" aria-label="Permalink to &quot;Fase 1: Basis (60 minuten)&quot;">​</a></h3><h4 id="_1-welkom-en-huisregels-15-min" tabindex="-1">1. Welkom en huisregels (15 min) <a class="header-anchor" href="#_1-welkom-en-huisregels-15-min" aria-label="Permalink to &quot;1. Welkom en huisregels (15 min)&quot;">​</a></h4><p><strong>Het sociale contract:</strong></p><div class="tip custom-block"><p class="custom-block-title">De Container - Essentiële basisregels</p><p>Voordat er informatie wordt gedeeld, moet de groep het eens zijn over het volgende:</p><ol><li><strong>Vertrouwelijkheid</strong> - Wat hier gezegd wordt, blijft hier.</li><li><strong>De Vegas-regel</strong> - Lessen verlaten de kamer, verhalen blijven.</li><li><strong>Niet repareren</strong> - Wees getuige en probeer te begrijpen, probeer het niet op te lossen.</li><li><strong>Recht om te passeren</strong> - Kwetsbaarheid kan niet worden afgedwongen</li><li><strong>Respecteer het proces</strong> - Vertrouw op het ongemak</li></ol></div><p><strong>Jouw script:</strong></p><blockquote><p>&quot;Welkom. Deze ruimte is anders dan de piste. Hier onderzoeken we wat er <em>vanbinnen</em> gebeurt als je boven die perfecte slag staat. Alles wat hier gedeeld wordt, is vertrouwelijk. De lessen die je leert, mag je meenemen, maar de persoonlijke verhalen blijven. Je bent hier niet om elkaar te repareren, maar om elkaar te begrijpen. En je mag altijd passen. Zijn jullie het hiermee eens?&quot;</p></blockquote><h4 id="_2-activiteit-de-incheckmatrix-20-min" tabindex="-1">2. Activiteit: De incheckmatrix (20 min) <a class="header-anchor" href="#_2-activiteit-de-incheckmatrix-20-min" aria-label="Permalink to &quot;2. Activiteit: De incheckmatrix (20 min)&quot;">​</a></h4><p><strong>Doel:</strong> Het normaliseren van het toegeven van vermoeidheid of stress.</p><p><strong>Materialen:</strong> Whiteboard of flipchart, plakbriefjes</p><p><strong>Procedure:</strong></p><ol><li>Teken een 2x2 matrix: Hoge/Lage energie (verticaal), Positief/Negatief (horizontaal)</li><li>Elke speler schrijft zijn of haar naam op een plakbriefje.</li><li>Plaats de notitie in hun huidige kwadrant.</li><li>Bespreking: &quot;We hebben drie mensen in de &#39;lage energie/negatieve&#39; stemming. Welke invloed heeft dit op onze sessie van vandaag?&quot;</li></ol>',12)),(i(),l(g,null,{default:d(()=>[r(b,{id:"mermaid-719",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BIncheckmatrix%5D%20--%3E%20B%5BVeel%20energie%20%2B%20positiviteit%5D%0A%20%20%20%20A%20--%3E%20C%5BHoge%20energie%20%2B%20negatief%5D%0A%20%20%20%20A%20--%3E%20D%5BLage%20energie%20%2B%20positief%5D%0A%20%20%20%20A%20--%3E%20E%5BLage%20energie%20%2B%20negatief%5D%0A%0A%20%20%20%20B%20--%3E%20F%5BErken%20alle%20staten%5D%0A%20%20%20%20C%20--%3E%20F%0A%20%20%20%20D%20--%3E%20F%0A%20%20%20%20E%20--%3E%20F%0A%0A%20%20%20%20style%20A%20fill%3A%23e8f5e9%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:d(()=>[...u[2]||(u[2]=[s(" Loading... ",-1)])]),_:1})),u[9]||(u[9]=o('<p><strong>Tips voor de begeleiding:</strong></p><ul><li>Beoordeel geen enkel kwadrant als &quot;slecht&quot;.</li><li>Vraag jezelf af: &quot;Wat heeft je lichaam op dit moment nodig?&quot;</li><li>Let op patronen: &quot;Jullie drieën bevinden zich in dezelfde ruimte - hoe komt dat?&quot;</li></ul><h4 id="_3-activiteit-de-ijsberg-van-petanque-25-min" tabindex="-1">3. Activiteit: De ijsberg van petanque (25 min) <a class="header-anchor" href="#_3-activiteit-de-ijsberg-van-petanque-25-min" aria-label="Permalink to &quot;3. Activiteit: De ijsberg van petanque (25 min)&quot;">​</a></h4><p><strong>Doel:</strong> Verborgen innerlijke gedachten visualiseren</p><p><strong>Materialen:</strong> Groot papier, stiften</p><p><strong>Procedure:</strong></p><ol><li>Teken een ijsberg op papier.</li><li><strong>Boven water:</strong> Schrijf &quot;Techniek, De worp, Het resultaat&quot; op.</li><li><strong>Onder water:</strong> Vraag: &quot;Wat speelt er zich af in je hoofd dat niemand ziet?&quot;</li></ol><p><strong>Aanwijzingen:</strong></p><ul><li>&quot;Waar ben je bang voor als je op het punt staat te schieten?&quot;</li><li>&quot;Voor welk oordeel bent u bezorgd?&quot;</li><li>&quot;Wat zegt je innerlijke stem als je mist?&quot;</li></ul><p><strong>De inzichtvraag:</strong></p><blockquote><p>&quot;Wat gebeurt er met je werparm als de &#39;onderwater&#39;-oefeningen te zwaar worden?&quot;</p></blockquote><p>Dit koppelt mentale belasting aan fysieke spanning (de bibber/yips).</p><details class="details custom-block"><summary>Veelvoorkomende reacties &quot;onder water&quot;</summary><ul><li>Angst om het team teleur te stellen</li><li>Maak je zorgen dat je er dom uitziet</li><li>Twijfel over het vermogen</li><li>Vergelijking met anderen</li><li>Druk om je waarde te bewijzen</li><li>Angst voor oordeel van coach/teamgenoten</li><li>Impostersyndroom</li></ul></details>',13)),r(v),u[10]||(u[10]=o('<h3 id="fase-2-geconcentreerd-werk-90-minuten" tabindex="-1">Fase 2: Geconcentreerd werk (90 minuten) <a class="header-anchor" href="#fase-2-geconcentreerd-werk-90-minuten" aria-label="Permalink to &quot;Fase 2: Geconcentreerd werk (90 minuten)&quot;">​</a></h3><h4 id="_4-activiteit-de-gebruikershandleiding-30-min" tabindex="-1">4. Activiteit: De gebruikershandleiding (30 min) <a class="header-anchor" href="#_4-activiteit-de-gebruikershandleiding-30-min" aria-label="Permalink to &quot;4. Activiteit: De gebruikershandleiding (30 min)&quot;">​</a></h4><p><strong>Doel:</strong> Empathie in de praktijk brengen - teamleden helpen elkaar te begrijpen</p><p><strong>Materialen:</strong> Werkbladen (één per speler)</p><p><strong>Het sjabloon voor de gebruikershandleiding:</strong></p><table tabindex="0"><thead><tr><th>Sectie</th><th>Snel</th><th>Voorbeeld</th></tr></thead><tbody><tr><td><strong>Mijn stressprofiel</strong></td><td>&quot;Als ik angstig ben, dan...&quot;</td><td>&quot;...helemaal stil worden&quot;</td></tr><tr><td><strong>Hoe moet je met mij omgaan?</strong></td><td>&quot;Als ik een cruciale kans mis, moet ik...&quot;</td><td>&quot;...stilte, geen aanmoediging&quot;</td></tr><tr><td><strong>Mijn innerlijke gedachte</strong></td><td>&quot;De leugen die ik mezelf vertel is...&quot;</td><td>&quot;...dat ik niet goed genoeg ben&quot;</td></tr><tr><td><strong>Mijn trigger</strong></td><td>&quot;Ik ga in de verdediging als...&quot;</td><td>&quot;...iemand stelt mijn schotkeuze ter discussie&quot;</td></tr></tbody></table><p><strong>Procedure:</strong></p><ol><li>Geef de spelers 10 minuten om de opdracht in stilte af te ronden.</li><li>Ga de ronde doen - iedereen deelt ÉÉN gedeelte.</li><li>Anderen kunnen verduidelijkende vragen stellen (geen advies!).</li><li>De coördinator valideert elk aandeel.</li></ol><p><strong>Facilitatiescript:</strong></p><blockquote><p>&quot;Dit is je handleiding. Als je teamgenoot weet dat je stil wordt als je nerveus bent, zal hij of zij het niet persoonlijk opvatten. Als ze weten dat je stilte nodig hebt na een gemiste kans, zullen ze niet proberen je te &#39;corrigeren&#39;. Zo bouwen we aan teamintelligentie.&quot;</p></blockquote><h4 id="_5-de-link-leggen-tussen-websitecontent-en-innerlijke-gedachten-30-min" tabindex="-1">5. De link leggen tussen websitecontent en innerlijke gedachten (30 min) <a class="header-anchor" href="#_5-de-link-leggen-tussen-websitecontent-en-innerlijke-gedachten-30-min" aria-label="Permalink to &quot;5. De link leggen tussen websitecontent en innerlijke gedachten (30 min)&quot;">​</a></h4><p><strong>Doel:</strong> De kloof overbruggen tussen technische inhoud en psychologische ervaring.</p><p>Kies 2-3 onderdelen van de Academy-website en verken het innerlijke spel:</p><p><strong>Voorbeeld 1: Techniek - De greep en het loslaten</strong></p><p><strong>De vertrouwensvraag:</strong></p><blockquote><p>&quot;Voelt je hand bij een stand van 12-12 in een toernooi dan ook aan zoals in de techniekbeschrijving? Zijn het de spieren die veranderen, of de gedachte &#39;Laat hem niet vallen&#39;, die je grip verandert?&quot;</p></blockquote><p><strong>De microtremor:</strong></p><blockquote><p>&quot;Wie van jullie voelt de &#39;microtrilling&#39; van angst? Welke innerlijke gedachte veroorzaakt dat?&quot;</p></blockquote><p><strong>Voorbeeld 2: Tactiek - Richten versus Schieten</strong></p><p><strong>Risicoprofiel:</strong></p><blockquote><p>&quot;Als de gids zegt &#39;Schiet om te winnen&#39;, is je reactie dan opwinding of angst? Wat zegt dat over jouw relatie met risico?&quot;</p></blockquote><p><strong>De bedrieger:</strong></p><blockquote><p>&quot;Richt je wel eens terwijl je <em>weet</em> dat je zou moeten schieten, puur om de schaamte van een misser te voorkomen? Wat is de prijs van die veiligheid?&quot;</p></blockquote><p><strong>Voorbeeld 3: Voeding - Wedstrijddag</strong></p><p><strong>De valkuil van troostvoedsel:</strong></p><blockquote><p>&quot;Eet je wat je lichaam nodig heeft of wat je angst je ingeeft? Hoe weet je het verschil?&quot;</p></blockquote><div class="tip custom-block"><p class="custom-block-title">Facilitatietechniek</p><p>Geef geen college over de inhoud. Stel vragen die de technische informatie verbinden met hun eigen ervaringen. Het inzicht komt van HEN, niet van jou.</p></div><h4 id="_6-activiteit-angst-in-een-hoed-30-min" tabindex="-1">6. Activiteit: Angst in een hoed (30 min) <a class="header-anchor" href="#_6-activiteit-angst-in-een-hoed-30-min" aria-label="Permalink to &quot;6. Activiteit: Angst in een hoed (30 min)&quot;">​</a></h4><p><strong>Doel:</strong> Doorbreek de isolatiecirkel - laat zien dat lotgenoten dezelfde diepe onzekerheden delen.</p><p><strong>Materialen:</strong> Papier, pen, hoed/tas</p><p><strong>Procedure:</strong></p><ol><li>Iedereen schrijft anoniem een diepe angst over zijn of haar carrière of team op.</li><li>Vouw de papieren en meng ze in een hoed.</li><li>Iedere speler trekt een briefje (niet van zichzelf).</li><li>Lees het hardop voor</li><li>Onderbouw het: &quot;Ik begrijp waarom iemand zich zo zou voelen, want...&quot;</li></ol><p><strong>Voorbeelden van angsten:</strong></p><ul><li>&quot;Ik ben bang dat ik mijn hoogtepunt heb bereikt en nooit meer beter zal worden.&quot;</li><li>&quot;Ik ben bang dat mijn teamgenoten denken dat ik overschat word.&quot;</li><li>&quot;Ik ben bang dat ik op het cruciale moment zal bezwijken onder de druk.&quot;</li><li>&quot;Ik ben bang dat ik vervangen word door jongere spelers.&quot;</li></ul><p><strong>De kracht:</strong> Wanneer spelers hun geheime angst hardop horen voorlezen en bevestigd zien door leeftgenoten, verdwijnt de schaamte. Ze beseffen: &quot;Ik ben niet alleen. Dit is normaal.&quot;</p><p><strong>Rol van de coördinator:</strong></p><ul><li>Erken ELKE angst als legitiem</li><li>Bagatelliseer het niet: &quot;Dat is niet waar!&quot; ontkracht het gevoel.</li><li>Vraag: &quot;Hoeveel van jullie hebben iets soortgelijks meegemaakt?&quot;</li></ul>',37)),(i(),l(g,null,{default:d(()=>[r(b,{id:"mermaid-1100",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BAngst%20in%20een%20hoed%5D%20--%3E%20B%5BAnoniem%20delen%5D%0A%20%20%20%20B%20--%3E%20C%5BPeervalidatie%5D%0A%20%20%20%20C%20--%3E%20D%5BSchaamte%20verdwijnt%5D%0A%20%20%20%20D%20--%3E%20E%5BIsolatiepauzes%5D%0A%20%20%20%20E%20--%3E%20F%5BPsychologische%20veiligheid%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffe4e1%0A%20%20%20%20style%20F%20fill%3A%23e8f5e9%0A"})]),fallback:d(()=>[...u[3]||(u[3]=[s(" Loading... ",-1)])]),_:1})),u[11]||(u[11]=o('<h3 id="fase-3-integratie-45-minuten" tabindex="-1">Fase 3: Integratie (45 minuten) <a class="header-anchor" href="#fase-3-integratie-45-minuten" aria-label="Permalink to &quot;Fase 3: Integratie (45 minuten)&quot;">​</a></h3><h4 id="_7-activiteit-de-innerlijke-criticus-herformuleren-25-min" tabindex="-1">7. Activiteit: De innerlijke criticus herformuleren (25 min) <a class="header-anchor" href="#_7-activiteit-de-innerlijke-criticus-herformuleren-25-min" aria-label="Permalink to &quot;7. Activiteit: De innerlijke criticus herformuleren (25 min)&quot;">​</a></h4><p><strong>Doel:</strong> Cognitieve herstructurering - verandering van de interne dialoog</p><p><strong>Materialen:</strong> Werkblad</p><p><strong>Procedure:</strong></p><p><strong>Stap 1: Identificeer de criticus (10 min)</strong></p><blockquote><p>&quot;Schrijf de PRECIES de woorden op die je innerlijke criticus zegt na een mislukking. Niet de beleefde versie, maar de keiharde.&quot;</p></blockquote><p>Voorbeelden:</p><ul><li>&quot;Je faalt altijd&quot;</li><li>&quot;Iedereen kijkt toe hoe je faalt&quot;</li><li>&quot;Je maakt jezelf belachelijk&quot;</li><li>&quot;Je hoort hier niet thuis&quot;</li></ul><p><strong>Stap 2: Herkaderen als innerlijke coach (10 min)</strong></p><blockquote><p>&quot;Herschrijf dat nu als je innerlijke coach - streng maar ondersteunend.&quot;</p></blockquote><p>Voorbeelden:</p><ul><li>Criticus: &quot;Je faalt altijd&quot; → Coach: &quot;Neem even rust en haal diep adem. Volgende poging.&quot;</li><li>Criticus: &quot;Iedereen kijkt toe hoe je faalt&quot; → Coach: &quot;Focus op het doel, niet op het publiek&quot;</li><li>Criticus: &quot;Je maakt jezelf belachelijk&quot; → Coach: &quot;Eén slag tegelijk. Je hebt dit al eerder gedaan.&quot;</li></ul><p><strong>Stap 3: Oefening met een partner (5 min)</strong></p><blockquote><p>&quot;Deel je coachzin met een partner. Die zal je eraan herinneren wanneer de criticus in je naar boven komt.&quot;</p></blockquote><h4 id="_8-brug-naar-de-piste-20-min" tabindex="-1">8. Brug naar de piste (20 min) <a class="header-anchor" href="#_8-brug-naar-de-piste-20-min" aria-label="Permalink to &quot;8. Brug naar de piste (20 min)&quot;">​</a></h4><p><strong>Doel:</strong> Ontwikkel concrete protocollen voor de competitie.</p><p><strong>Discussievragen:</strong></p><ol><li>&quot;Wat is ÉÉN ding van vandaag dat je in je volgende wedstrijd zult gebruiken?&quot;</li><li>&quot;Hoe weten je teamgenoten dat je ondersteuning nodig hebt?&quot;</li><li>&quot;Wat is jouw signaal voor &#39;Ik heb een mentale reset nodig&#39;?&quot;</li></ol><p><strong>Stel teamprotocollen op:</strong></p><table tabindex="0"><thead><tr><th>Situatie</th><th>Protocol</th><th>Voorbeeld</th></tr></thead><tbody><tr><td><strong>Na een misser</strong></td><td>Raadpleeg de gebruikershandleiding.</td><td>&quot;Marc heeft stilte nodig, Lisa heeft een high five nodig.&quot;</td></tr><tr><td><strong>Druk voelen</strong></td><td>Gebruik de coach-uitdrukking.</td><td>&quot;Reset en haal diep adem&quot;</td></tr><tr><td><strong>Teamspanning</strong></td><td>Oproep time-out</td><td>&quot;Laten we 2 minuten nemen&quot;</td></tr><tr><td><strong>Innerlijke criticus luidt zijn stem</strong></td><td>Fysieke reset</td><td>Raak de boules aan, haal diep adem</td></tr></tbody></table><h3 id="fase-4-afsluiting-15-minuten" tabindex="-1">Fase 4: Afsluiting (15 minuten) <a class="header-anchor" href="#fase-4-afsluiting-15-minuten" aria-label="Permalink to &quot;Fase 4: Afsluiting (15 minuten)&quot;">​</a></h3><h4 id="_9-de-uitcheckprocedure-10-min" tabindex="-1">9. De uitcheckprocedure (10 min) <a class="header-anchor" href="#_9-de-uitcheckprocedure-10-min" aria-label="Permalink to &quot;9. De uitcheckprocedure (10 min)&quot;">​</a></h4><p><strong>Procedure:</strong> Ga de kring rond, iedereen deelt:</p><ol><li><strong>Wat neem je mee?</strong> &quot;Welk inzicht of welke tool neem je mee naar huis?&quot;</li><li><strong>Eén ding dat je achterlaat:</strong> &quot;Waar laat je afscheid van?&quot;</li></ol><p><strong>Rol van de coördinator:</strong></p><ul><li>Bedank iedereen voor hun bijdrage.</li><li>Valideer het uitgevoerde werk.</li><li>Herinner aan de vertrouwelijkheid.</li></ul><h4 id="_10-vervolgprotocol-5-min" tabindex="-1">10. Vervolgprotocol (5 min) <a class="header-anchor" href="#_10-vervolgprotocol-5-min" aria-label="Permalink to &quot;10. Vervolgprotocol (5 min)&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Cruciaal: Voorkom een kater na een kwetsbaarheid.</p><p>Diepgaand werk kan een &quot;kwetsbaarheidskater&quot; veroorzaken - spijt of schaamte over het delen van ervaringen.</p><p><strong>Uw 24-uursprotocol:</strong></p><ul><li>Stuur een bericht naar iedereen die binnen 24 uur veel berichten heeft gedeeld.</li><li>Bericht: &quot;Dankjewel voor je moed gisteren. Wat je deelde heeft iedereen geholpen.&quot;</li><li>Vraag: &quot;Hoe voelt u zich na de sessie?&quot;</li></ul></div><p><strong>Afsluitend script:</strong></p><blockquote><p>&quot;Wat hier vandaag is gebeurd, vergde moed. Jullie waren er, jullie stelden je open en jullie vertrouwden op het proces. Diezelfde moed laten jullie ook zien op de piste. Onthoud: de lessen verlaten deze ruimte, maar de verhalen blijven. Dank jullie wel.&quot;</p></blockquote>',31)),r(v),u[12]||(u[12]=o('<h2 id="hanteerweerstand" tabindex="-1">Hanteerweerstand <a class="header-anchor" href="#hanteerweerstand" aria-label="Permalink to &quot;Hanteerweerstand&quot;">​</a></h2><h3 id="de-quot-te-coole-quot-atleet" tabindex="-1">De &quot;te coole&quot; atleet <a class="header-anchor" href="#de-quot-te-coole-quot-atleet" aria-label="Permalink to &quot;De &amp;quot;te coole&amp;quot; atleet&quot;">​</a></h3><p><strong>Scenario:</strong> Een speler rolt met zijn ogen tijdens een kwetsbaarheidsoefening.</p><p><strong>Strategie:</strong> Verbale Aikido (Uitlijnen en Draaien)</p><p><strong>Script:</strong></p><blockquote><p>&quot;Ik zie die reactie, [Naam]. Eerlijk gezegd snap ik het. Praten over gevoelens voelt soft. Maar de piste is oncomfortabel. Als we het ongemak van deze ruimte niet aankunnen, trainen we onze tolerantie voor het ongemak van het spel niet. Kun je me 20 minuten vertrouwen?&quot;</p></blockquote><h3 id="de-stille-deelnemer" tabindex="-1">De stille deelnemer <a class="header-anchor" href="#de-stille-deelnemer" aria-label="Permalink to &quot;De stille deelnemer&quot;">​</a></h3><p><strong>Scenario:</strong> Iemand heeft al 45 minuten niets gezegd.</p><p><strong>Strategie:</strong> Creëer een laagdrempelig instapmoment.</p><p><strong>Script:</strong></p><blockquote><p>&quot;[Naam], ik merk dat je alles in je opneemt. Wat is één ding dat je tot nu toe het meest is bijgebleven? Al is het maar één woord.&quot;</p></blockquote><h3 id="de-persoon-die-alles-te-veel-deelt" tabindex="-1">De persoon die alles te veel deelt <a class="header-anchor" href="#de-persoon-die-alles-te-veel-deelt" aria-label="Permalink to &quot;De persoon die alles te veel deelt&quot;">​</a></h3><p><strong>Scenario:</strong> Iemand domineert met lange verhalen</p><p><strong>Strategie:</strong> Zachte omleiding</p><p><strong>Script:</strong></p><blockquote><p>&quot;Dankjewel daarvoor, [Naam]. Ik wil ervoor zorgen dat iedereen de ruimte krijgt. Laten we eens horen van iemand die nog niets heeft gedeeld.&quot;</p></blockquote><h3 id="de-oplosser" tabindex="-1">De Oplosser <a class="header-anchor" href="#de-oplosser" aria-label="Permalink to &quot;De Oplosser&quot;">​</a></h3><p><strong>Scenario:</strong> Iemand probeert de problemen van anderen op te lossen.</p><p><strong>Strategie:</strong> Versterk de basisregels</p><p><strong>Script:</strong></p><blockquote><p>&quot;Ik waardeer je bereidheid om te helpen, maar onthoud onze regel: observeer en probeer te begrijpen, los het niet op. [Oorspronkelijke spreker], wat heb je nu nodig?&quot;</p></blockquote><h2 id="materialenlijst" tabindex="-1">Materialenlijst <a class="header-anchor" href="#materialenlijst" aria-label="Permalink to &quot;Materialenlijst&quot;">​</a></h2><details class="details custom-block"><summary>Workshopmaterialen</summary><p><strong>Fysieke opstelling:</strong></p><ul><li>[ ] Stoelen (6-8, geen tafels)</li><li>[ ] Jeu de boules en cochonnet voor het midden</li><li>[ ] Flipchart of whiteboard</li><li>[ ] Markeringen</li></ul><p><strong>Activiteiten:</strong></p><ul><li>[ ] Plakbriefjes (Incheckmatrix)</li><li>[ ] Groot papier (IJsbergactiviteit)</li><li>[ ] Werkbladen voor de gebruikershandleiding</li><li>[ ] Papier en pennen (Angst in een hoed)</li><li>[ ] Werkbladen voor de innerlijke criticus/coach</li></ul><p><strong>Logistiek:</strong></p><ul><li>[ ] Water voor de deelnemers</li><li>[ ] Zakdoekjes (emotioneel werk!)</li><li>[ ] Timer (houd je aan het schema)</li><li>[ ] Contactlijst van deelnemers (voor follow-up)</li></ul></details><h2 id="coordinator-zelfzorg" tabindex="-1">Coördinator Zelfzorg <a class="header-anchor" href="#coordinator-zelfzorg" aria-label="Permalink to &quot;Coördinator Zelfzorg&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Jij hebt ook ondersteuning nodig.</p><p>Ruimte bieden aan kwetsbaarheid is emotioneel veeleisend.</p><p><strong>Na de workshop:</strong></p><ul><li>Bespreek de resultaten met een collega of leidinggevende.</li><li>Schrijf op wat er bij je opkwam.</li><li>Maak een wandeling of neem een fysieke pauze.</li><li>Neem hun verhalen niet mee naar huis.</li></ul></div><h2 id="impact-meten" tabindex="-1">Impact meten <a class="header-anchor" href="#impact-meten" aria-label="Permalink to &quot;Impact meten&quot;">​</a></h2><h3 id="directe-feedback" tabindex="-1">Directe feedback <a class="header-anchor" href="#directe-feedback" aria-label="Permalink to &quot;Directe feedback&quot;">​</a></h3><p>Stel tot slot de volgende vraag:</p><ol><li>&quot;Op een schaal van 1 tot 10, hoe veilig voelde je je vandaag om iets te delen?&quot;</li><li>&quot;Wat is één ding dat de volgende sessie zou verbeteren?&quot;</li></ol><h3 id="langetermijnmonitoring" tabindex="-1">Langetermijnmonitoring <a class="header-anchor" href="#langetermijnmonitoring" aria-label="Permalink to &quot;Langetermijnmonitoring&quot;">​</a></h3><p>Vervolgconsult na 2-4 weken:</p><ul><li>&quot;Heb je al gereedschap uit de werkplaats gebruikt?&quot;</li><li>&quot;Hoe is je relatie met je innerlijke criticus veranderd?&quot;</li><li>&quot;Wat is er anders aan jullie mentaliteit ten aanzien van de wedstrijd?&quot;</li></ul><h2 id="volgende-stappen" tabindex="-1">Volgende stappen <a class="header-anchor" href="#volgende-stappen" aria-label="Permalink to &quot;Volgende stappen&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Voortbouwend op dit fundament</p><p>Deze workshop is fase 1. Overweeg het volgende:</p><ul><li><strong>Vervolgsessies</strong> (online of persoonlijk)</li><li><strong>Integratie op de piste</strong> (zie handleiding trainingssessie)</li><li><strong>Teamprotocollen</strong> (Gebruikershandleidingen implementeren tijdens de wedstrijd)</li><li><strong>Individuele check-ins</strong> (voor spelers die meer ondersteuning nodig hebben)</li></ul></div>',34)),r(k)])}]]);export{u as __pageData,h as default};
